fun touchWay(row: Int,way: Int,fill: Boolean) {
    if(replacement=="LRU"||replacement=="FIFO"&&fill)touched[row][way]=++clock else if(replacement=="PLRU") {
        var low=0;
        var high=ways;
        var node=1;
        while(high-low>1) {
            val mid=(low+high)/2;
            if(way<mid) {
                bits[row][node]=1;
                high=mid;
                node*=2
            }else {
                bits[row][node]=0;
                low=mid;
                node=2*node+1
            }
        }
    }
}
fun touch(block: Int) {
    val p=locate(block)?:return;
    touchWay(p.row,p.way,false)
}
fun requester(protocol: String,old: String,op: String,otherHasLine: Boolean): Request {
    if(protocol=="VI")return if(op=="R")Request(if(old=="I")"BusRd" else null,"V") else Request("BusWr",
        if(old=="I")"I" else "V");
    if(old=="I")return if(op=="W")Request("BusRdX","M") else Request("BusRd",if(protocol!="MSI"&&!otherHasLine)"E" else "S");
    if(op=="R")return Request(null,old);
    return if(old=="M"||old=="E")Request(null,"M") else Request("BusUpgr","M")
}
